import crypto from 'node:crypto';
const fail=(code,status=400)=>{throw Object.assign(Error(code),{status})};
const paymentKey=id=>'lab_domain_payment:'+id,requestKey=(lab,domain)=>'lab_domain_request:'+lab+':'+domain;
async function transaction(pool,fn){const c=await pool.connect();try{await c.query('BEGIN');const result=await fn(c);await c.query('COMMIT');return result}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}
async function save(c,key,value){await c.query('UPDATE platform_settings SET value=$2::jsonb,updated_at=now() WHERE key=$1',[key,JSON.stringify(value)]);}
export async function startDomainCheckout({pool,labId,userId,domains,quotes,gateway,merchant,multiplier,publicOrigin}){
 if(!merchant||!Number.isFinite(multiplier)||multiplier<=0)fail('domain_gateway_not_configured',503);
 const prepared=await transaction(pool,async c=>{const rows=[];for(const domain of [...domains].sort()){const q=await c.query('SELECT value FROM platform_settings WHERE key=$1 FOR UPDATE',[requestKey(labId,domain)]);const r=q.rows[0]?.value;if(!r)fail('request_not_found',404);rows.push(r);}
 const existing=[...new Set(rows.map(r=>r.gatewayCheckoutId).filter(Boolean))];if(existing.length){if(existing.length!==1||rows.some(r=>r.gatewayCheckoutId!==existing[0]))fail('domain_checkout_pending',409);const p=(await c.query('SELECT value FROM platform_settings WHERE key=$1',[paymentKey(existing[0])])).rows[0]?.value;if(!p||JSON.stringify([...p.domains].sort())!==JSON.stringify([...domains].sort())||rows.some(r=>quotes?.[r.domain]!==p.quotes[r.domain]))fail('domain_checkout_pending',409);if(p.status==='paid')return {paid:true,paymentId:p.id};if(p.status==='pending'&&p.trackId)return {paymentId:p.id,paymentUrl:'https://gateway.zibal.ir/start/'+encodeURIComponent(p.trackId),amount:p.amount};fail('domain_checkout_pending',409);}
 let amount=0;for(const r of rows){if(r.status!=='quoted'||r.paymentStatus==='paid'||r.quoteId!==quotes?.[r.domain]||!Number.isFinite(Date.parse(r.quoteExpiresAt))||Date.parse(r.quoteExpiresAt)<Date.now()||!Number.isSafeInteger(r.amount)||r.amount<1)fail('domain_quote_changed',409);amount+=r.amount;}
 const gatewayAmount=amount*multiplier;if(!Number.isSafeInteger(gatewayAmount)||gatewayAmount<=0)fail('invalid_domain_amount');
 const id=crypto.randomUUID(),value={id,labId,userId,domains:[...domains].sort(),quotes:Object.fromEntries(rows.map(r=>[r.domain,r.quoteId])),items:rows.map(r=>({domain:r.domain,quoteId:r.quoteId,baseAmount:r.baseAmount,taxAmount:r.taxAmount,taxPercent:r.taxPercent,amount:r.amount})),amount,gatewayAmount,status:'creating',createdAt:new Date().toISOString()};
 await c.query('INSERT INTO platform_settings(key,value,updated_at) VALUES($1,$2::jsonb,now())',[paymentKey(id),JSON.stringify(value)]);for(const r of rows){r.gatewayCheckoutId=id;await save(c,requestKey(labId,r.domain),r)}return {record:value};});
 if(!prepared.record)return prepared;const p=prepared.record;let response;
 try{response=await gateway('request',{merchant,amount:p.gatewayAmount,callbackUrl:publicOrigin+'/api/payments/zibal/domain/callback?paymentId='+p.id,orderId:p.id,description:'PhotoBridge · ثبت دامنه '+p.domains.join('، ')});}catch{await pool.query("UPDATE platform_settings SET value=value||'{\"status\":\"request_unknown\"}'::jsonb,updated_at=now() WHERE key=$1",[paymentKey(p.id)]);fail('domain_gateway_request_unknown',503)}
 if(Number(response?.result)!==100||!/^\d+$/.test(String(response.trackId||''))){await transaction(pool,async c=>{p.status='request_failed';await save(c,paymentKey(p.id),p);for(const domain of p.domains){const key=requestKey(labId,domain),q=await c.query('SELECT value FROM platform_settings WHERE key=$1 FOR UPDATE',[key]),r=q.rows[0]?.value;if(r?.gatewayCheckoutId===p.id){delete r.gatewayCheckoutId;await save(c,key,r)}}});fail('domain_gateway_request_failed',502)}
 p.trackId=String(response.trackId);p.status='pending';await save(pool,paymentKey(p.id),p);return {paymentId:p.id,paymentUrl:'https://gateway.zibal.ir/start/'+p.trackId,amount:p.amount};
}
export async function confirmDomainPayment({pool,paymentId,trackId,orderId,gateway,merchant}){
 const row=(await pool.query('SELECT value FROM platform_settings WHERE key=$1',[paymentKey(paymentId)])).rows[0]?.value;
 if(!row||!row.trackId||String(row.trackId)!==String(trackId)||(orderId&&orderId!==row.id))fail('domain_payment_mismatch',400);
 if(row.status==='paid')return row;
 const verified=await gateway('verify',{merchant,trackId:String(trackId)});if(verified?.orderId&&String(verified.orderId)!==row.id)fail('domain_payment_mismatch',409);if(![100,201].includes(Number(verified?.result))){if(Number(verified?.result)===202&&Number(verified?.status)===3){await releaseDomainCheckout({pool,paymentId:row.id,reason:'cancelled',requireUnknown:false});fail('domain_payment_cancelled',409)}fail('domain_payment_not_verified',409);}
 let proof=verified;if(Number(proof.amount)>0&&Number(proof.amount)!==Number(row.gatewayAmount))fail('domain_payment_amount_mismatch',409);if(!(Number(proof.amount)>0)){proof=await gateway('inquiry',{merchant,trackId:String(trackId)});if(Number(proof?.result)!==100||![1,2].includes(Number(proof.status)))fail('domain_payment_not_verified',409);}
 if(proof?.orderId&&String(proof.orderId)!==row.id)fail('domain_payment_mismatch',409);
 if(Number(proof.amount)!==Number(row.gatewayAmount)||!Number(proof.amount))fail('domain_payment_amount_mismatch',409);
 return transaction(pool,async c=>{
 // Match checkout lock order: request rows first, then payment row.
 const requests=[];for(const domain of [...row.domains].sort()){const q=await c.query('SELECT value FROM platform_settings WHERE key=$1 FOR UPDATE',[requestKey(row.labId,domain)]);requests.push(q.rows[0]?.value);}
 const current=(await c.query('SELECT value FROM platform_settings WHERE key=$1 FOR UPDATE',[paymentKey(row.id)])).rows[0]?.value;if(current.status==='paid')return current;
 if(String(current.trackId)!==String(trackId))fail('domain_payment_mismatch',409);
 for(const r of requests){if(!r||r.gatewayCheckoutId!==row.id||r.quoteId!==row.quotes[r.domain])fail('domain_quote_changed',409);Object.assign(r,{paymentStatus:'paid',paymentMethod:'gateway',paymentTransactionId:row.id,status:'paid_pending_registration',paidAt:new Date().toISOString(),gatewayTrackId:row.trackId,gatewayRefNumber:String(verified.refNumber||proof.refNumber||'')});await save(c,requestKey(row.labId,r.domain),r);}
 Object.assign(current,{status:'paid',paidAt:new Date().toISOString(),gatewayRefNumber:String(verified.refNumber||proof.refNumber||''),smsState:'pending'});await save(c,paymentKey(current.id),current);return current;
 });
}
export async function dispatchDomainAdminAlert({pool,notifyAdmin},id){const q=await pool.query("UPDATE platform_settings SET value=value||'{\"smsState\":\"dispatching\"}'::jsonb,updated_at=now() WHERE key=$1 AND value->>'status'='paid' AND value->>'smsState'='pending' RETURNING value",[paymentKey(id)]);const p=q.rows[0]?.value;if(!p)return;
 try{const lab=(await pool.query('SELECT name FROM labs WHERE id=$1',[p.labId])).rows[0];const message='PhotoBridge\nسفارش دامنه پرداخت شد\n'+(lab?.name||'لابراتوار')+'\n'+p.domains.join('\n')+'\nمبلغ با مالیات: '+Number(p.amount).toLocaleString('fa-IR')+' تومان\nپیگیری: '+p.trackId+'\nپنل ادمین: سفارش‌های دامنه';const sent=await notifyAdmin(message,p.labId);if(!sent?.sent)throw Error('admin_sms_not_sent');await pool.query("UPDATE platform_settings SET value=value||$2::jsonb,updated_at=now() WHERE key=$1",[paymentKey(id),JSON.stringify({smsState:'sent',smsReference:sent.reference||null})]);}
 catch(e){await pool.query("UPDATE platform_settings SET value=value||$2::jsonb,updated_at=now() WHERE key=$1",[paymentKey(id),JSON.stringify({smsState:'failed',smsError:String(e?.message||'sms_failed').slice(0,200)})]);}
}
export function startDomainAlertWorker(deps){let running=false;const tick=async()=>{if(running)return;running=true;try{const rows=await deps.pool.query("SELECT value FROM platform_settings WHERE key LIKE 'lab_domain_payment:%' AND value->>'status'='paid' AND value->>'smsState'='pending' ORDER BY updated_at LIMIT 10");for(const row of rows.rows)await dispatchDomainAdminAlert(deps,row.value.id)}catch(e){console.error('[domain-alert-worker]',String(e?.message||e))}finally{running=false}};void tick();const timer=setInterval(()=>void tick(),30000);timer.unref?.();return timer;}
export async function handleDomainCallback({req,res,url,pool,gateway,merchant,publicOrigin,notifyAdmin}){
 if(url.pathname!=='/api/payments/zibal/domain/callback')return false;
 const id=String(url.searchParams.get('paymentId')||''),trackId=String(url.searchParams.get('trackId')||''),orderId=String(url.searchParams.get('orderId')||'');let result='unverified';
 if(req.method==='GET'&&/^[a-f0-9-]{36}$/i.test(id)&&/^\d+$/.test(trackId)&&merchant){try{await confirmDomainPayment({pool,paymentId:id,trackId,orderId,gateway,merchant});result='success';void dispatchDomainAdminAlert({pool,notifyAdmin},id).catch(()=>{});}catch(e){if(e?.message==='domain_payment_cancelled')result='cancelled';console.error('[domain-payment-callback]',String(e?.message||e))}}
 res.writeHead(302,{location:publicOrigin+'/lab/settings/site?domainPayment='+result,'cache-control':'no-store'});res.end();return true;
}

export async function releaseDomainCheckout({pool,paymentId,reason='abandoned',requireUnknown=true}){const row=(await pool.query('SELECT value FROM platform_settings WHERE key=$1',[paymentKey(paymentId)])).rows[0]?.value;if(!row)fail('payment_not_found',404);return transaction(pool,async c=>{const requests=[];for(const domain of [...row.domains].sort()){const q=await c.query('SELECT value FROM platform_settings WHERE key=$1 FOR UPDATE',[requestKey(row.labId,domain)]);requests.push(q.rows[0]?.value);}const p=(await c.query('SELECT value FROM platform_settings WHERE key=$1 FOR UPDATE',[paymentKey(paymentId)])).rows[0]?.value;if(p.status==='paid')fail('domain_order_already_paid',409);if(requireUnknown&&(p.trackId||!['creating','request_unknown'].includes(p.status)||Date.parse(p.createdAt)>Date.now()-120000))fail('domain_checkout_pending',409);for(const r of requests){if(r?.gatewayCheckoutId===paymentId&&r.paymentStatus!=='paid'){delete r.gatewayCheckoutId;await save(c,requestKey(row.labId,r.domain),r)}}p.status=reason;p.closedAt=new Date().toISOString();await save(c,paymentKey(paymentId),p);return p;});}
